func TestCacheKeySortsParams(t *testing.T) {
	c := &Client{}
	params := map[string]string{
		"siteId":       "10",
		"index":        "1",
		"getChecksums": "0",
	}

	got := c.cacheKey("/order_products/123/prepare", params)
	const want = "49ad8435204781e8"
	if got != want {
		t.Fatalf("cacheKey = %q, want %q", got, want)
	}

	reordered := map[string]string{
		"getChecksums": "0",
		"siteId":       "10",
		"index":        "1",
	}
	if gotAgain := c.cacheKey("/order_products/123/prepare", reordered); gotAgain != got {
		t.Fatalf("cacheKey changed for equivalent params: %q != %q", gotAgain, got)
	}
}

func TestAuthHeaderUsesDriveThruTokenWithoutOAuthRefresh(t *testing.T) {
	c := &Client{
		Config: &config.Config{
			AccessToken:            "legacy-oauth-token",
			RefreshToken:           "legacy-refresh-token",
			TokenExpiry:            time.Now().Add(-time.Hour),
			DrivethrurpgDtrpgToken: "dtrpg-token",
		},
	}

	got, err := c.authHeader(context.Background())
	if err != nil {
		t.Fatalf("authHeader returned error: %v", err)
	}
	if got != "dtrpg-token" {
		t.Fatalf("authHeader = %q, want dtrpg-token", got)
	}
}

func TestExchangeApplicationKeyContextHonorsCancellation(t *testing.T) {
	c := New(&config.Config{BaseURL: "http://127.0.0.1:1"}, 10*time.Second, 0)
	ctx, cancel := context.WithCancel(context.Background())
	cancel()

	_, err := c.ExchangeApplicationKeyContext(ctx, "application-key")
	if !errors.Is(err, context.Canceled) {
		t.Fatalf("ExchangeApplicationKeyContext error = %v, want context.Canceled", err)
	}
}

